"""Compact forecasters used as REFERENCE models for keyed-holdout evidence (optional dependency: torch).
Channel-independent, per-window normalised (RevIN without affine): DLinear, MLP, PatchTST-lite.
An arbiter trains its own reference from the recipe committed in the signed release record."""
from __future__ import annotations

import numpy as np

try:
    import torch
    import torch.nn as nn
except ImportError as e:                                 # pragma: no cover
    raise ImportError("provenmark.models needs torch: pip install 'provenmark[torch]'") from e


class _Norm(nn.Module):
    def forward(self, x):
        mu, sd = x.mean(1, keepdim=True), x.std(1, keepdim=True) + 1e-6
        return (x - mu) / sd, mu, sd


class DLinear(nn.Module):
    def __init__(self, L, H, k=25):
        super().__init__()
        self.k, self.n = k, _Norm()
        self.trend, self.seas = nn.Linear(L, H), nn.Linear(L, H)

    def forward(self, x):
        z, mu, sd = self.n(x)
        pad = torch.cat([z[:, :1].repeat(1, (self.k - 1) // 2), z, z[:, -1:].repeat(1, self.k // 2)], 1)
        tr = pad.unfold(1, self.k, 1).mean(-1)
        return (self.trend(tr) + self.seas(z - tr)) * sd + mu


class MLP(nn.Module):
    def __init__(self, L, H, d=512):
        super().__init__()
        self.n = _Norm()
        self.net = nn.Sequential(nn.Linear(L, d), nn.ReLU(), nn.Linear(d, d), nn.ReLU(), nn.Linear(d, H))

    def forward(self, x):
        z, mu, sd = self.n(x)
        return self.net(z) * sd + mu


class PatchTST(nn.Module):
    def __init__(self, L, H, patch=16, stride=8, d=64, layers=2, heads=4):
        super().__init__()
        self.n, self.patch, self.stride = _Norm(), patch, stride
        N = (L - patch) // stride + 1
        self.emb = nn.Linear(patch, d)
        self.pos = nn.Parameter(torch.randn(1, N, d) * 0.02)
        enc = nn.TransformerEncoderLayer(d, heads, 2 * d, 0.1, batch_first=True, norm_first=True)
        self.enc = nn.TransformerEncoder(enc, layers, enable_nested_tensor=False)
        self.head = nn.Linear(N * d, H)

    def forward(self, x):
        z, mu, sd = self.n(x)
        h = self.enc(self.emb(z.unfold(1, self.patch, self.stride)) + self.pos)
        return self.head(h.flatten(1)) * sd + mu


ARCHS = {"dlinear": DLinear, "mlp": MLP, "patchtst": PatchTST}


def make_windows(series_list, L, H, stride):
    X, Y = [], []
    for x in series_list:
        idx = np.arange(0, len(x) - L - H + 1, stride)
        if idx.size:
            X.append(np.stack([x[i:i + L] for i in idx]).astype(np.float32))
            Y.append(np.stack([x[i + L:i + L + H] for i in idx]).astype(np.float32))
    return np.concatenate(X), np.concatenate(Y)


def train(arch, X, Y, L, H, epochs=5, bs=256, lr=1e-3, seed=0):
    torch.manual_seed(seed)
    np.random.seed(seed)
    m = ARCHS[arch](L, H)
    opt = torch.optim.Adam(m.parameters(), lr=lr)
    sched = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=lr, total_steps=max(1, epochs * ((len(X) + bs - 1) // bs)))
    Xt, Yt = torch.from_numpy(X), torch.from_numpy(Y)
    g = torch.Generator().manual_seed(seed)
    for _ in range(epochs):
        m.train()
        perm = torch.randperm(len(Xt), generator=g)
        for i in range(0, len(Xt), bs):
            b = perm[i:i + bs]
            loss = ((m(Xt[b]) - Yt[b]) ** 2).mean()
            opt.zero_grad(); loss.backward(); opt.step(); sched.step()
    m.eval()
    return m


def as_forecast(m):
    def f(ctx):
        with torch.no_grad():
            return m(torch.from_numpy(np.asarray(ctx, dtype=np.float32))).numpy().astype(np.float64)
    return f
